  "<section class=\"pg-sec\"><div class=\"pg-sec-head\"><b>最近の作業</b> <span class=\"muted small\">新しい順（くわしくは「ログ」で見られます）</span></div><ul class=\"pg-recent\">{v}</ul></section>": { en: "<section class=\"pg-sec\"><div class=\"pg-sec-head\"><b>Recent work</b> <span class=\"muted small\">Newest first (see the Log for details)</span></div><ul class=\"pg-recent\">{v}</ul></section>", es: "<section class=\"pg-sec\"><div class=\"pg-sec-head\"><b>Trabajo reciente</b> <span class=\"muted small\">Más reciente primero (el detalle está en el registro)</span></div><ul class=\"pg-recent\">{v}</ul></section>", fr: "<section class=\"pg-sec\"><div class=\"pg-sec-head\"><b>Travail récent</b> <span class=\"muted small\">Plus récent d’abord (détail dans le journal)</span></div><ul class=\"pg-recent\">{v}</ul></section>", zh: "<section class=\"pg-sec\"><div class=\"pg-sec-head\"><b>最近的工作</b> <span class=\"muted small\">新的在前（详情见「日志」）</span></div><ul class=\"pg-recent\">{v}</ul></section>" },
