  "<span class=\"repo-host local\" title=\"このマシンのリポジトリです。ホストには表示されません\">{v}<span class=\"repo-host-name\">このマシン</span></span>": { en: "<span class=\"repo-host local\" title=\"Repository on this machine. It is not shown on the host\">{v}<span class=\"repo-host-name\">This machine</span></span>", es: "<span class=\"repo-host local\" title=\"Repositorio de este equipo. No se muestra en el host\">{v}<span class=\"repo-host-name\">Este equipo</span></span>", fr: "<span class=\"repo-host local\" title=\"Dépôt de cette machine. Il n’apparaît pas sur l’hôte\">{v}<span class=\"repo-host-name\">Cette machine</span></span>", zh: "<span class=\"repo-host local\" title=\"这是本机的仓库，不会显示在主机上\">{v}<span class=\"repo-host-name\">本机</span></span>" },
