  "<div class=\"pg-chart-wrap sub-chart\"><div class=\"pg-chart\">{svg}</div><div class=\"zoom-host\">{v}</div></div><div class=\"pg-legend muted small\"><span class=\"lg lg-done\">完了</span><span class=\"lg lg-run\">実行中</span><span class=\"lg lg-warn\">止まっている・待っている</span><span class=\"lg lg-pending\">これから</span><span class=\"lg lg-skip\">スキップ</span> ・ サブタスクをクリックすると詳細を開きます</div>": {"en":"<div class=\"pg-chart-wrap sub-chart\"><div class=\"pg-chart\">{svg}</div><div class=\"zoom-host\">{v}</div></div><div class=\"pg-legend muted small\"><span class=\"lg lg-done\">Done</span><span class=\"lg lg-run\">Running</span><span class=\"lg lg-warn\">Stopped or waiting</span><span class=\"lg lg-pending\">Upcoming</span><span class=\"lg lg-skip\">Skipped</span> · Click a subtask to open its details</div>","es":"<div class=\"pg-chart-wrap sub-chart\"><div class=\"pg-chart\">{svg}</div><div class=\"zoom-host\">{v}</div></div><div class=\"pg-legend muted small\"><span class=\"lg lg-done\">Hecho</span><span class=\"lg lg-run\">En ejecución</span><span class=\"lg lg-warn\">Parado o en espera</span><span class=\"lg lg-pending\">Pendiente</span><span class=\"lg lg-skip\">Omitido</span> · Haz clic en una subtarea para ver sus detalles</div>","fr":"<div class=\"pg-chart-wrap sub-chart\"><div class=\"pg-chart\">{svg}</div><div class=\"zoom-host\">{v}</div></div><div class=\"pg-legend muted small\"><span class=\"lg lg-done\">Terminé</span><span class=\"lg lg-run\">En cours</span><span class=\"lg lg-warn\">Arrêté ou en attente</span><span class=\"lg lg-pending\">À venir</span><span class=\"lg lg-skip\">Ignoré</span> · Cliquez sur une sous-tâche pour voir ses détails</div>","zh":"<div class=\"pg-chart-wrap sub-chart\"><div class=\"pg-chart\">{svg}</div><div class=\"zoom-host\">{v}</div></div><div class=\"pg-legend muted small\"><span class=\"lg lg-done\">完成</span><span class=\"lg lg-run\">运行中</span><span class=\"lg lg-warn\">已停止或等待中</span><span class=\"lg lg-pending\">待办</span><span class=\"lg lg-skip\">跳过</span> · 点击子任务可打开详情</div>"},
  "<section class=\"pg-sec\"><div class=\"pg-sec-head\"><b>{v}サブタスクのフローチャート</b></div>{chart}</section>": {"en":"<section class=\"pg-sec\"><div class=\"pg-sec-head\"><b>{v}Subtask flowchart</b></div>{chart}</section>","es":"<section class=\"pg-sec\"><div class=\"pg-sec-head\"><b>{v}Diagrama de flujo de subtareas</b></div>{chart}</section>","fr":"<section class=\"pg-sec\"><div class=\"pg-sec-head\"><b>{v}Organigramme des sous-tâches</b></div>{chart}</section>","zh":"<section class=\"pg-sec\"><div class=\"pg-sec-head\"><b>{v}子任务流程图</b></div>{chart}</section>"},
  "<div class=\"sub-box sub-chat-box\"><div class=\"pg-sec-head\"><b>{v}サブタスク {done}/{total} 完了（{pct}%）</b> <span class=\"muted small\">{phase}</span></div>\n    <div class=\"pg-bar\" title=\"{pct}%\"><span style=\"width:{pct}%\"></span></div>\n    <div class=\"d-actions\"><button class=\"btn small\" data-sact=\"openTab\" type=\"button\">{v2}サブタスクの進捗を見る</button></div></div>": {"en":"<div class=\"sub-box sub-chat-box\"><div class=\"pg-sec-head\"><b>{v}Subtasks {done}/{total} done ({pct}%)</b> <span class=\"muted small\">{phase}</span></div>\n    <div class=\"pg-bar\" title=\"{pct}%\"><span style=\"width:{pct}%\"></span></div>\n    <div class=\"d-actions\"><button class=\"btn small\" data-sact=\"openTab\" type=\"button\">{v2}View subtask progress</button></div></div>","es":"<div class=\"sub-box sub-chat-box\"><div class=\"pg-sec-head\"><b>{v}Subtareas {done}/{total} hechas ({pct}%)</b> <span class=\"muted small\">{phase}</span></div>\n    <div class=\"pg-bar\" title=\"{pct}%\"><span style=\"width:{pct}%\"></span></div>\n    <div class=\"d-actions\"><button class=\"btn small\" data-sact=\"openTab\" type=\"button\">{v2}Ver el progreso de las subtareas</button></div></div>","fr":"<div class=\"sub-box sub-chat-box\"><div class=\"pg-sec-head\"><b>{v}Sous-tâches {done}/{total} terminées ({pct} %)</b> <span class=\"muted small\">{phase}</span></div>\n    <div class=\"pg-bar\" title=\"{pct}%\"><span style=\"width:{pct}%\"></span></div>\n    <div class=\"d-actions\"><button class=\"btn small\" data-sact=\"openTab\" type=\"button\">{v2}Voir l’avancement des sous-tâches</button></div></div>","zh":"<div class=\"sub-box sub-chat-box\"><div class=\"pg-sec-head\"><b>{v}子任务 {done}/{total} 已完成（{pct}%）</b> <span class=\"muted small\">{phase}</span></div>\n    <div class=\"pg-bar\" title=\"{pct}%\"><span style=\"width:{pct}%\"></span></div>\n    <div class=\"d-actions\"><button class=\"btn small\" data-sact=\"openTab\" type=\"button\">{v2}查看子任务进度</button></div></div>"},
